#include <bits/stdc++.h>

using namespace std;
bool check(int pos, int l, int r, int n, vector < int > & indx) {
    for (int j = 0; j < indx.size(); j++) {
        int i = indx[j];
        int pc = min(i, l) + max(0, i - n + r);
        int sfc = max(0, l - i + 1) + min(r, n - i + 1);
        bool pv = false;
        bool sv = false;
        if (pos <= i && pc == (i - 1) / 2) pv = true;
        if (pos >= i && sfc == (n - i) / 2) sv = true;
        if (!pv && !sv) return false;
    }
    return true;

}

int main() {
    int mod = 998244353;
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector < vector < int >> indx(n + 1);
        for (int i = 1; i <= n; i++) {
            int val;
            cin >> val;
            indx[val].push_back(i);
        }
        vector < int > dp(n + 1, 0);
        dp[0] = 1;
        for (int val = 1; val <= n; val++) {
            vector < int > next(n + 1, 0);
            for (int l = 0; l < val; l++) {
                if (dp[l] == 0) continue;
                int r = val - 1 - l;
                int pos = l + 1;
                if (check(pos, l, r, n, indx[val])) {
                    next[l+1] += dp[l];
                    if (next[l+1] >= mod) next[l+1] -= mod;
                    
                }
                if(val<n){
                    pos=n-r;
                    if(check(pos,l,r,n,indx[val])){
                        next[l]+=dp[l];
                        if(next[l]>=mod){
                            next[l]-=mod;
                        }
                    }
                    
                }
                
            }
            dp = next;

        }
        int ans = 0;
        for (int i = 0; i <= n; i++) {
            ans += dp[i];
            if (ans >= mod) ans -= mod;
        }
        cout << ans << endl;

    }
    return 0;



}
